"use client";

import type { FormHTMLAttributes, ReactNode } from "react";

import {
  FormProvider,
  type FieldValues,
  type SubmitErrorHandler,
  type SubmitHandler,
  type UseFormReturn,
} from "react-hook-form";

export type FormProps<
  TFieldValues extends FieldValues,
  TContext = object,
  TTransformedValues = TFieldValues,
> = Omit<FormHTMLAttributes<HTMLFormElement>, "onSubmit"> & {
  methods: UseFormReturn<TFieldValues, TContext, TTransformedValues>;
  onSubmit: SubmitHandler<TTransformedValues>;
  onInvalid?: SubmitErrorHandler<TFieldValues>;
  children: ReactNode;
};

export function Form<
  TFieldValues extends FieldValues,
  TContext = object,
  TTransformedValues = TFieldValues,
>({
  methods,
  onSubmit,
  onInvalid,
  children,
  noValidate = true,
  ...formProps
}: FormProps<TFieldValues, TContext, TTransformedValues>) {
  return (
    <FormProvider<TFieldValues, TContext, TTransformedValues> {...methods}>
      <form
        {...formProps}
        noValidate={noValidate}
        onSubmit={methods.handleSubmit(onSubmit, onInvalid)}
      >
        {children}
      </form>
    </FormProvider>
  );
}

"use client";

import { useId } from "react";

import {
  Controller,
  useFormContext,
  type FieldPath,
  type FieldValues,
} from "react-hook-form";

import {
  Field,
  FieldContent,
  FieldDescription,
  FieldError,
  FieldLabel,
} from "@/components/ui/field";

import { cn } from "@/lib/utils";

import type {
  FormFieldBaseProps,
  FormFieldIds,
  FormFieldRenderProps,
} from "./form-types";

export type FormFieldProps<
  TFieldValues extends FieldValues,
  TName extends FieldPath<TFieldValues>,
  TTransformedValues = TFieldValues,
> = FormFieldBaseProps<TFieldValues, TName, TTransformedValues>;

export function FormField<
  TFieldValues extends FieldValues,
  TName extends FieldPath<TFieldValues>,
  TTransformedValues = TFieldValues,
>({
  name,
  render,
  label,
  description,
  className,
  orientation = "vertical",
  labelPlacement = "start",
  showError = true,
  required = false,
  disabled,
  rules,
  shouldUnregister,
  defaultValue,
}: FormFieldProps<TFieldValues, TName, TTransformedValues>) {
  const { control } = useFormContext<
    TFieldValues,
    object,
    TTransformedValues
  >();

  const reactId = useId();

  const ids: FormFieldIds = {
    control: `field-${reactId}-control`,
    description: `field-${reactId}-description`,
    error: `field-${reactId}-error`,
  };

  return (
    <Controller<TFieldValues, TName, TTransformedValues>
      name={name}
      control={control}
      rules={rules}
      disabled={disabled}
      shouldUnregister={shouldUnregister}
      defaultValue={defaultValue}
      render={({ field, fieldState, formState }) => {
        const invalid = fieldState.invalid;
        const isDisabled = Boolean(disabled || field.disabled);

        const ariaDescribedBy =
          [
            description ? ids.description : undefined,
            showError && invalid ? ids.error : undefined,
          ]
            .filter(Boolean)
            .join(" ") || undefined;

        const context: FormFieldRenderProps<
          TFieldValues,
          TName,
          TTransformedValues
        > = {
          field,
          fieldState,
          formState,
          ids,
          invalid,
          required,
          disabled: isDisabled,
          ariaDescribedBy,
        };

        const labelNode = label ? (
          <FieldLabel htmlFor={ids.control}>
            {label}
            {required && (
              <span aria-hidden="true" className="text-destructive">
                {" "}
                *
              </span>
            )}
          </FieldLabel>
        ) : null;

        const descriptionNode = description ? (
          <FieldDescription id={ids.description}>
            {description}
          </FieldDescription>
        ) : null;

        const errorNode =
          showError && invalid ? (
            <FieldError id={ids.error} errors={[fieldState.error]} />
          ) : null;

        const controlNode = render(context);

        const metadataNode = (
          <>
            {labelNode}
            {descriptionNode}
            {errorNode}
          </>
        );

        return (
          <Field
            data-invalid={invalid || undefined}
            data-disabled={isDisabled || undefined}
            orientation={orientation}
            className={cn(className)}
          >
            {orientation === "vertical" ? (
              <>
                {labelNode}
                {controlNode}
                {descriptionNode}
                {errorNode}
              </>
            ) : (
              <>
                {labelPlacement === "start" && (
                  <FieldContent>{metadataNode}</FieldContent>
                )}

                {controlNode}

                {labelPlacement === "end" && (
                  <FieldContent>{metadataNode}</FieldContent>
                )}
              </>
            )}
          </Field>
        );
      }}
    />
  );
}

"use client";

import { useId } from "react";

import {
  Controller,
  useFormContext,
  type FieldPath,
  type FieldValues,
} from "react-hook-form";

import {
  FieldDescription,
  FieldError,
  FieldGroup,
  FieldLegend,
  FieldSet,
} from "@/components/ui/field";

import { cn } from "@/lib/utils";

import type {
  FormFieldBaseProps,
  FormFieldIds,
  FormFieldRenderProps,
} from "./form-types";

import type { ReactNode } from "react";

export type FormFieldSetProps<
  TFieldValues extends FieldValues,
  TName extends FieldPath<TFieldValues>,
  TTransformedValues = TFieldValues,
> = Omit<
  FormFieldBaseProps<TFieldValues, TName, TTransformedValues>,
  "label" | "orientation" | "labelPlacement"
> & {
  legend?: ReactNode;
  legendVariant?: "legend" | "label";
};

export function FormFieldSet<
  TFieldValues extends FieldValues,
  TName extends FieldPath<TFieldValues>,
  TTransformedValues = TFieldValues,
>({
  name,
  render,
  legend,
  description,
  className,
  legendVariant = "legend",
  showError = true,
  required = false,
  disabled,
  rules,
  shouldUnregister,
  defaultValue,
}: FormFieldSetProps<TFieldValues, TName, TTransformedValues>) {
  const { control } = useFormContext<
    TFieldValues,
    object,
    TTransformedValues
  >();

  const reactId = useId();

  const ids: FormFieldIds = {
    control: `fieldset-${reactId}-control`,
    description: `fieldset-${reactId}-description`,
    error: `fieldset-${reactId}-error`,
  };

  return (
    <Controller<TFieldValues, TName, TTransformedValues>
      name={name}
      control={control}
      rules={rules}
      disabled={disabled}
      shouldUnregister={shouldUnregister}
      defaultValue={defaultValue}
      render={({ field, fieldState, formState }) => {
        const invalid = fieldState.invalid;
        const isDisabled = Boolean(disabled || field.disabled);

        const ariaDescribedBy =
          [
            description ? ids.description : undefined,
            showError && invalid ? ids.error : undefined,
          ]
            .filter(Boolean)
            .join(" ") || undefined;

        const context: FormFieldRenderProps<
          TFieldValues,
          TName,
          TTransformedValues
        > = {
          field,
          fieldState,
          formState,
          ids,
          invalid,
          required,
          disabled: isDisabled,
          ariaDescribedBy,
        };

        return (
          <FieldSet
            disabled={isDisabled}
            data-invalid={invalid || undefined}
            data-disabled={isDisabled || undefined}
            aria-describedby={ariaDescribedBy}
            className={cn(className)}
          >
            {legend && (
              <FieldLegend id={ids.control} variant={legendVariant}>
                {legend}

                {required && (
                  <span aria-hidden="true" className="text-destructive">
                    {" "}
                    *
                  </span>
                )}
              </FieldLegend>
            )}

            {description && (
              <FieldDescription id={ids.description}>
                {description}
              </FieldDescription>
            )}

            {render(context)}

            {showError && invalid && (
              <FieldError id={ids.error} errors={[fieldState.error]} />
            )}
          </FieldSet>
        );
      }}
    />
  );
}

import { Field } from "@/components/ui/field";
import type { ComponentProps, ReactElement, ReactNode } from "react";

import type {
    ControllerProps,
    FieldPath,
    FieldPathByValue,
    FieldValues,
} from "react-hook-form";

export type FormOrientation =
    ComponentProps<typeof Field>["orientation"];

export type FormLabelPlacement = "start" | "end";

export type FormFieldIds = {
    control: string;
    description: string;
    error: string;
};

export type FormFieldRenderProps<
    TFieldValues extends FieldValues,
    TName extends FieldPath<TFieldValues>,
    TTransformedValues = TFieldValues,
> = Parameters<
    ControllerProps<
        TFieldValues,
        TName,
        TTransformedValues
    >["render"]
>[0] & {
    ids: FormFieldIds;
    invalid: boolean;
    required: boolean;
    disabled: boolean;
    ariaDescribedBy?: string;
};

export type FormFieldRules<
    TFieldValues extends FieldValues,
    TName extends FieldPath<TFieldValues>,
    TTransformedValues = TFieldValues,
> = ControllerProps<
    TFieldValues,
    TName,
    TTransformedValues
>["rules"];

export type FormFieldBaseProps<
    TFieldValues extends FieldValues,
    TName extends FieldPath<TFieldValues>,
    TTransformedValues = TFieldValues,
> = {
    name: TName;
    render: (
        props: FormFieldRenderProps<
            TFieldValues,
            TName,
            TTransformedValues
        >
    ) => ReactElement;
    label?: ReactNode;
    description?: ReactNode;
    className?: string;
    orientation?: FormOrientation;
    labelPlacement?: FormLabelPlacement;
    showError?: boolean;
    required?: boolean;
    disabled?: boolean;
    rules?: FormFieldRules<
        TFieldValues,
        TName,
        TTransformedValues
    >;
    shouldUnregister?: boolean;
    defaultValue?: ControllerProps<
        TFieldValues,
        TName,
        TTransformedValues
    >["defaultValue"];
};

export type CheckboxOption = {
    value: string;
    label: ReactNode;
    description?: ReactNode;
    disabled?: boolean;
};

export type SelectOption = {
    value: string;
    label: ReactNode;
    disabled?: boolean;
};

export type RadioOption = SelectOption & {
    description?: ReactNode;
};

export type StringFieldName<
    TFieldValues extends FieldValues,
> = FieldPathByValue<
    TFieldValues,
    string | null | undefined
>;

export type NumberFieldName<
    TFieldValues extends FieldValues,
> = FieldPathByValue<
    TFieldValues,
    number | null | undefined
>;

export type BooleanFieldName<
    TFieldValues extends FieldValues,
> = FieldPathByValue<
    TFieldValues,
    boolean | null | undefined
>;

export type DateFieldName<
    TFieldValues extends FieldValues,
> = FieldPathByValue<
    TFieldValues,
    Date | null | undefined
>;

export type StringArrayFieldName<
    TFieldValues extends FieldValues,
> = FieldPathByValue<
    TFieldValues,
    string[] | null | undefined
>;

"use client";

import type { ComponentProps } from "react";
import type { FieldValues } from "react-hook-form";

import { Input } from "@/components/ui/input";

import { FormField, type FormFieldProps } from "../core/form-field";

import type { StringFieldName } from "../core/form-types";

export type FormInputProps<
  TFieldValues extends FieldValues,
  TName extends StringFieldName<TFieldValues>,
> = Omit<
  ComponentProps<typeof Input>,
  | "name"
  | "value"
  | "defaultValue"
  | "onChange"
  | "onBlur"
  | "disabled"
  | "required"
  | "id"
  | "aria-invalid"
  | "aria-describedby"
> &
  Omit<FormFieldProps<TFieldValues, TName>, "name" | "render" | "className"> & {
    name: TName;
    fieldClassName?: string;
  };

export function FormInput<
  TFieldValues extends FieldValues,
  TName extends StringFieldName<TFieldValues>,
>({
  name,
  label,
  description,
  orientation,
  labelPlacement,
  showError,
  rules,
  shouldUnregister,
  required,
  disabled,
  defaultValue,
  fieldClassName,
  className,
  ...inputProps
}: FormInputProps<TFieldValues, TName>) {
  return (
    <FormField
      name={name}
      label={label}
      description={description}
      orientation={orientation}
      labelPlacement={labelPlacement}
      showError={showError}
      rules={rules}
      shouldUnregister={shouldUnregister}
      required={required}
      disabled={disabled}
      defaultValue={defaultValue}
      className={fieldClassName}
      render={({
        field,
        ids,
        invalid,
        required: isRequired,
        disabled: isDisabled,
        ariaDescribedBy,
      }) => (
        <Input
          {...inputProps}
          {...field}
          id={ids.control}
          value={field.value ?? ""}
          disabled={isDisabled}
          required={isRequired}
          aria-invalid={invalid || undefined}
          aria-describedby={ariaDescribedBy}
          className={className}
        />
      )}
    />
  );
}

"use client";

import type { ComponentProps } from "react";
import type { FieldValues } from "react-hook-form";

import { Input } from "@/components/ui/input";

import { FormField, type FormFieldProps } from "../core/form-field";

import type { NumberFieldName } from "../core/form-types";

export type FormNumberInputProps<
  TFieldValues extends FieldValues,
  TName extends NumberFieldName<TFieldValues>,
> = Omit<
  ComponentProps<typeof Input>,
  | "name"
  | "type"
  | "value"
  | "defaultValue"
  | "onChange"
  | "onBlur"
  | "disabled"
  | "required"
  | "id"
  | "aria-invalid"
  | "aria-describedby"
> &
  Omit<FormFieldProps<TFieldValues, TName>, "name" | "render" | "className"> & {
    name: TName;
    fieldClassName?: string;
    min?: number;
    max?: number;
    step?: number;
  };

export function FormNumberInput<
  TFieldValues extends FieldValues,
  TName extends NumberFieldName<TFieldValues>,
>({
  name,
  label,
  description,
  orientation,
  labelPlacement,
  showError,
  rules,
  shouldUnregister,
  required,
  disabled,
  defaultValue,
  fieldClassName,
  className,
  min,
  max,
  step,
  ...inputProps
}: FormNumberInputProps<TFieldValues, TName>) {
  return (
    <FormField
      name={name}
      label={label}
      description={description}
      orientation={orientation}
      labelPlacement={labelPlacement}
      showError={showError}
      rules={rules}
      shouldUnregister={shouldUnregister}
      required={required}
      disabled={disabled}
      defaultValue={defaultValue}
      className={fieldClassName}
      render={({
        field,
        ids,
        invalid,
        required: isRequired,
        disabled: isDisabled,
        ariaDescribedBy,
      }) => (
        <Input
          {...inputProps}
          name={field.name}
          ref={field.ref}
          type="number"
          id={ids.control}
          value={field.value ?? ""}
          onChange={(event) => {
            const rawValue = event.currentTarget.value;
            const numericValue = event.currentTarget.valueAsNumber;

            field.onChange(
              rawValue === "" || Number.isNaN(numericValue)
                ? null
                : numericValue,
            );
          }}
          onBlur={field.onBlur}
          min={min}
          max={max}
          step={step}
          disabled={isDisabled}
          required={isRequired}
          aria-invalid={invalid || undefined}
          aria-describedby={ariaDescribedBy}
          className={className}
        />
      )}
    />
  );
}

