    name: TName;
    fieldClassName?: string;
  };

export function FormCheckbox<
  TFieldValues extends FieldValues,
  TName extends BooleanFieldName<TFieldValues>,
>({
  name,
  label,
  description,
  orientation = "horizontal",
  labelPlacement = "end",
  showError,
  rules,
  shouldUnregister,
  required,
  disabled,
  defaultValue,
  fieldClassName,
  className,
