"use client";

import { Loader2 } from "lucide-react";
import type { ComponentProps, ReactNode } from "react";
import { useFormContext, useFormState } from "react-hook-form";

import { Button } from "@/components/ui/button";

export type FormSubmitButtonProps = Omit<
  ComponentProps<typeof Button>,
  "type" | "disabled" | "children"
> & {
  children?: ReactNode;
  loader?: ReactNode;
  loadingText?: string;
  disabled?: boolean;
  disableWhileSubmitting?: boolean;
};

export function FormSubmitButton({
  children = "Submit",
  loader,
  loadingText = "Submitting...",
  disabled = false,
  disableWhileSubmitting = true,
  className,
  ...buttonProps
}: FormSubmitButtonProps) {
  const { control } = useFormContext();
  const { isSubmitting } = useFormState({ control });

  const isDisabled = disabled || (disableWhileSubmitting && isSubmitting);

  const loaderComp = loader ?? <Loader2 className="size-4 animate-spin" />;
  return (
    <Button
      {...buttonProps}
      type="submit"
      disabled={isDisabled}
      aria-busy={isSubmitting || undefined}
      className={className}
    >
      {isSubmitting && loaderComp}

      {isSubmitting ? loadingText : children}
    </Button>
  );
}

"use client";

import type { ComponentProps, ReactNode } from "react";
import { useFormContext } from "react-hook-form";

import { Button } from "@/components/ui/button";

type ButtonOnClick = NonNullable<ComponentProps<typeof Button>["onClick"]>;

export type FormResetButtonProps = Omit<
  ComponentProps<typeof Button>,
  "type" | "children"
> & {
  children?: ReactNode;
};

export function FormResetButton({
  children = "Reset",
  onClick,
  ...buttonProps
}: FormResetButtonProps) {
  const { reset } = useFormContext();

  const handleReset: ButtonOnClick = (event) => {
    onClick?.(event);

    if (event.defaultPrevented) {
      return;
    }

    reset();
  };

  return (
    <Button {...buttonProps} type="button" onClick={handleReset}>
      {children}
    </Button>
  );
}

